#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
exit $fail
# every rendered form action URL must use a query key allowed by the function URL
for f in event seat refund; do
  while read -r u; do
    k=${u#\?}; k=${k%%=*}
    [[ "$k" =~ ^[A-Za-z0-9_.-]+$ ]] || { echo "bad query key: $u"; fail=1; }
  done < <(bash bin/render $f | grep -o 'action="[^"]*"' | sed 's/action="//;s/"$//')
done
exit $fail

